"""The candidates of the challenge set: generated by agents, run by the harness, labelled.

generate lets one model work on every starting version the plan gives it (pipeline_agent),
with short runs; it needs the model's key, so the user runs it. run trains every
candidate of a split once in the harness as candidates are judged (3 epochs, restarted
after the first, full evaluation), and the healthy project uninterrupted on every seed
as the reference; it needs the GPU and no key. label runs the hidden tests on every
candidate (challenge_set.label). Agent candidates come from their episodes, versions
as they are from pipeline_tasks, partial repairs from challenge_set; an evidence-removed
candidate has no run or label of its own but its parent's. smoke tries a model in the
loop before it writes candidates: two development faults, short runs on synthetic
data, and whether every call was answered, by which model and within the output
limit.

Agents work in folders named by a hash of their candidate (artifacts/workspaces), so
that no path a traceback shows names a version, task or split. An episode that ended in
an API error is tried again in a new attempt folder; nothing is deleted. Short runs,
candidate runs and contract results are kept by what they depend on (the modules, the
family, the seed), so identical candidates are trained and tested once.

    python -m runsleuth.candidates generate --split development \\
        --model gemini-3.5-flash-lite --provider gemini
    python -m runsleuth.candidates run --split development
    python -m runsleuth.candidates label --split development
    python -m runsleuth.candidates smoke --model-name gpt-6-luna \\
        --provider compatible --model gpt-6-luna
"""

import argparse
import hashlib
import json
import tempfile
import time
from collections import Counter
from collections.abc import Callable
from dataclasses import asdict
from datetime import UTC, datetime
from pathlib import Path
from typing import Any

from runsleuth import challenge_set, pipeline_agent, pipeline_tasks
from runsleuth.challenge_set import SEEDS_FILE, Candidate
from runsleuth.llm_client import PROVIDERS, create_llm_client
from runsleuth.pipeline_contract import run_contract_in_subprocess
from runsleuth.pipeline_tasks import HEALTHY, STATEMENT_NAME
from runsleuth.pipeline_workspace import run_in_subprocess

ROOT = Path("artifacts/candidates")
WORKSPACES = Path("artifacts/workspaces")
# The data and configuration every family's runs use.
DATA = {
    "camelyon_pipeline": ("camelyon", Path("configs/camelyon17_clean.json")),
    "ham10000_pipeline": ("ham10000", Path("configs/ham10000.json")),
}
EPOCHS = 3
SMOKE_ROOT = Path("artifacts/smoke-pipeline")
# One development fault of each family, trained on synthetic samples.
SMOKE_STARTS = (
    ("camelyon_pipeline", "positions_index_base"),
    ("ham10000_pipeline", "epoch_count_not_restored"),
)
SMOKE_DATA = {
    "camelyon_pipeline": ("synthetic", None),
    "ham10000_pipeline": ("synthetic_ham", None),
}
FINISHED = ("finished", "tool_call_limit", "no_tool_call")


def _sha256(value: Any) -> str:
    return hashlib.sha256(json.dumps(value, sort_keys=True).encode()).hexdigest()


def _read(path: Path) -> Any:
    return json.loads(Path(path).read_text(encoding="utf-8"))


def _write(path: Path, value: Any) -> None:
    path = Path(path)
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(json.dumps(value, indent=2) + "\n", encoding="utf-8")


def candidates(split: str) -> list[Candidate]:
    """The split's plan, on the drawn test seeds once they exist."""
    seeds = None
    if split == "test":
        if not SEEDS_FILE.exists():
            raise FileNotFoundError(f"The test seeds are drawn at the freeze, into {SEEDS_FILE}")
        seeds = tuple(_read(SEEDS_FILE)["seeds"])
    return challenge_set.plan(split, seeds)


def key(candidate: Candidate) -> str:
    """The neutral name of a candidate's folders."""
    return hashlib.sha256(candidate.id.encode()).hexdigest()[:16]


def write_project(directory: Path, sources: dict[str, str], statement: str) -> Path:
    directory = Path(directory)
    directory.mkdir(parents=True)
    for module, source in sources.items():
        (directory / f"{module}.py").write_text(source, encoding="utf-8", newline="\n")
    (directory / STATEMENT_NAME).write_text(statement, encoding="utf-8", newline="\n")
    return directory


def _project_sources(project: Path) -> dict[str, str]:
    return {
        name.removesuffix(".py"): (Path(project) / name).read_text(encoding="utf-8")
        for name in pipeline_agent.MODULE_FILES
    }


class Runner:
    """Trains projects in the harness and keeps every outcome by what it depends on."""

    def __init__(
        self,
        root: Path,
        *,
        data: dict[str, tuple[str, Path | None]] = DATA,
        run: Callable[..., dict[str, Any]] = run_in_subprocess,
        device: str = "auto",
    ) -> None:
        self.root, self.data, self._run, self.device = Path(root), data, run, device

    def train(
        self, sources: dict[str, str], family: str, seed: int, *, tag: str = "", **settings: Any
    ) -> dict[str, Any]:
        """The outcome of training a project, trained once for every setting; seconds is
        how long the training took when it ran. A tag trains once more what another tag
        trained, as a check of whether training repeats."""
        source, config = self.data[family]
        digest = _sha256(
            {"sources": sources, "family": family, "seed": seed, "data": source, **settings}
            | ({"tag": tag} if tag else {})
        )[:24]
        kept = self.root / digest / "outcome.json"
        if kept.exists():
            return _read(kept)
        # A run stopped before its outcome was kept leaves its folder; the next starts anew.
        attempt = 1
        while (self.root / digest / f"run-{attempt}").exists():
            attempt += 1
        started = time.monotonic()
        with tempfile.TemporaryDirectory() as directory:
            project = write_project(Path(directory) / "project", sources, "")
            outcome = self._run(
                project,
                self.root / digest / f"run-{attempt}",
                data=source,
                config=config,
                seed=seed,
                device=self.device,
                **settings,
            )
        outcome = {**outcome, "seconds": round(time.monotonic() - started, 1)}
        _write(kept, outcome)
        return outcome


def generate(
    split: str,
    model_name: str,
    client: Any,
    model: str,
    *,
    root: Path = ROOT,
    workspaces: Path = WORKSPACES,
    runner: Runner | None = None,
    echo_reasoning: bool = False,
    pause: float = 0.0,
    progress: Callable[[str], None] = print,
) -> list[dict[str, Any]]:
    """Let one model work on every starting version the plan gives it, once each.

    An episode that ended in an API error is tried again in a new attempt folder.
    """
    runner = runner or Runner(Path(workspaces) / "short_runs")
    written = []
    for candidate in candidates(split):
        if candidate.origin != "agent" or candidate.model != model_name:
            continue
        path = Path(root) / split / "episodes" / f"{key(candidate)}.json"
        if path.exists() and _read(path)["record"]["status"] in FINISHED:
            continue
        attempt = 1
        while (Path(workspaces) / key(candidate) / f"attempt-{attempt}").exists():
            attempt += 1
        family = pipeline_tasks.family(candidate.family)
        project = write_project(
            Path(workspaces) / key(candidate) / f"attempt-{attempt}" / "project",
            pipeline_tasks.version_sources(candidate.start, candidate.family),
            family.statement,
        )

        def short_run(folder: Path, candidate: Candidate = candidate) -> dict[str, Any]:
            outcome = runner.train(
                _project_sources(folder),
                candidate.family,
                candidate.seed,
                epochs=pipeline_agent.SHORT_RUN["epochs"],
                interrupt_after_epochs=pipeline_agent.SHORT_RUN["interrupt_after_epochs"],
                max_eval_samples=pipeline_agent.SHORT_RUN["max_eval_samples"],
            )
            return pipeline_agent.shown_run(outcome)

        started = datetime.now(UTC)
        record = pipeline_agent.run_agent(
            client,
            model,
            project,
            run_training=short_run,
            echo_reasoning=echo_reasoning,
            pause=pause,
        )
        episode = {
            "schema_version": 1,
            "task": "candidate_episode",
            "candidate": asdict(candidate),
            "attempt": attempt,
            "started_at": started.isoformat(timespec="seconds"),
            "seconds": round((datetime.now(UTC) - started).total_seconds(), 1),
            "record": record,
            "sources": _project_sources(project),
        }
        _write(path, episode)
        written.append(episode)
        claim = record["claim"] or {}
        progress(f"{candidate.id}: {record['status']}, claims {claim.get('project_is_correct')}")
    return written


def candidate_sources(candidate: Candidate, root: Path = ROOT) -> dict[str, str] | None:
    """A candidate's modules; None for an agent candidate whose episode has not finished."""
    if candidate.kind == "repair":
        path = Path(root) / candidate.split / "episodes" / f"{key(candidate)}.json"
        if not path.exists():
            return None
        episode = _read(path)
        return episode["sources"] if episode["record"]["status"] in FINISHED else None
    if candidate.kind == "partial_repair":
        return challenge_set.partial_sources(candidate.start)
    return pipeline_tasks.version_sources(candidate.start, candidate.family)


def run_all(
    split: str,
    *,
    root: Path = ROOT,
    runner: Runner | None = None,
    progress: Callable[[str], None] = print,
) -> dict[str, Any]:
    """Train the healthy reference on every seed and every candidate that has sources;
    write runs.json, which names every run report."""
    runner = runner or Runner(Path(root) / split / "runs")
    planned = candidates(split)
    references = {}
    for family, seed in sorted({(c.family, c.seed) for c in planned}):
        outcome = runner.train(
            pipeline_tasks.version_sources(HEALTHY, family), family, seed, epochs=EPOCHS
        )
        references[f"{family}/{seed}"] = outcome
        progress(f"reference {family} seed {seed}: {outcome['status']}")
    runs = {}
    for candidate in planned:
        sources = candidate_sources(candidate, root)
        if candidate.kind == "evidence_removed" or sources is None:
            continue
        outcome = runner.train(
            sources, candidate.family, candidate.seed, epochs=EPOCHS, interrupt_after_epochs=1
        )
        runs[candidate.id] = outcome
        progress(f"{candidate.id}: {outcome['status']}")
    record = {"schema_version": 1, "task": "candidate_runs", "references": references, "runs": runs}
    _write(Path(root) / split / "runs.json", record)
    return record


def label_all(
    split: str,
    *,
    root: Path = ROOT,
    contract: Callable[..., dict[str, Any]] = run_contract_in_subprocess,
    progress: Callable[[str], None] = print,
) -> dict[str, Any]:
    """Run the hidden tests on every candidate that has sources; write labels.json."""
    kept_dir = Path(root) / split / "contract"
    labels = {}
    planned = candidates(split)
    by_id = {candidate.id: candidate for candidate in planned}
    for candidate in planned:
        if candidate.kind == "evidence_removed":
            continue
        sources = candidate_sources(candidate, root)
        if sources is None:
            continue
        kept = kept_dir / f"{_sha256({'sources': sources, 'family': candidate.family})[:24]}.json"
        if kept.exists():
            result = _read(kept)
        else:
            with tempfile.TemporaryDirectory() as directory:
                project = write_project(Path(directory) / "project", sources, "")
                result = contract(project, candidate.family)
            _write(kept, result)
        labels[candidate.id] = challenge_set.label(result, candidate.family)
        progress(f"{candidate.id}: {labels[candidate.id]['label']}")
    for candidate in planned:
        if candidate.kind == "evidence_removed" and candidate.parent in labels:
            labels[candidate.id] = labels[candidate.parent]
    record = {"schema_version": 1, "task": "candidate_labels", "labels": labels}
    _write(Path(root) / split / "labels.json", record)
    missing = [c.id for c in by_id.values() if c.id not in labels]
    if missing:
        progress(f"{len(missing)} candidates have no label yet (no finished episode)")
    return record


def summary_text(split: str, root: Path = ROOT) -> str:
    """How far a split has come: episodes, runs and labels."""
    planned = candidates(split)
    episodes = Path(root) / split / "episodes"
    statuses = (
        Counter(_read(path)["record"]["status"] for path in sorted(episodes.glob("*.json")))
        if episodes.exists()
        else Counter()
    )
    lines = [f"{split}: {len(planned)} candidates planned", f"episodes: {dict(statuses)}"]
    for name in ("runs.json", "labels.json"):
        path = Path(root) / split / name
        lines.append(f"{name}: {'written' if path.exists() else 'not yet'}")
    if (Path(root) / split / "labels.json").exists():
        labels = _read(Path(root) / split / "labels.json")["labels"]
        lines.append(f"labels: {dict(Counter(item['label'] for item in labels.values()))}")
    return "\n".join(lines)


def _passed_smoke(record: dict[str, Any]) -> bool:
    limit = record.get("limits", {}).get("max_output_tokens")
    return record["status"] == "finished" and limit == pipeline_agent.MAX_OUTPUT_TOKENS


def smoke(
    model_name: str,
    client: Any,
    model: str,
    *,
    root: Path = SMOKE_ROOT,
    runner: Runner | None = None,
    echo_reasoning: bool = False,
    pause: float = 0.0,
    progress: Callable[[str], None] = print,
) -> list[dict[str, Any]]:
    """Two episodes of a model on development faults, with short runs on synthetic data.
    An episode is kept once it finished under the loop's current limits; any other is
    tried again in a new folder."""
    runner = runner or Runner(Path(root) / "short_runs", data=SMOKE_DATA)
    episodes = []
    for family, start in SMOKE_STARTS:
        path = Path(root) / model_name / f"{family}.json"
        kept = _read(path) if path.exists() else None
        if kept and _passed_smoke(kept["record"]):
            episodes.append(kept)
            continue
        if kept:
            # The earlier episode is kept beside the new one, under its attempt.
            path.rename(path.with_name(f"{family}.attempt-{kept['attempt']}.json"))
        folder = hashlib.sha256(f"{model_name}/{family}".encode()).hexdigest()[:16]
        attempt = 1
        while (Path(root) / "work" / folder / f"attempt-{attempt}").exists():
            attempt += 1
        project = write_project(
            Path(root) / "work" / folder / f"attempt-{attempt}" / "project",
            pipeline_tasks.version_sources(start, family),
            pipeline_tasks.family(family).statement,
        )

        def short_run(project_dir: Path, family: str = family) -> dict[str, Any]:
            outcome = runner.train(
                _project_sources(project_dir),
                family,
                7,
                epochs=pipeline_agent.SHORT_RUN["epochs"],
                interrupt_after_epochs=pipeline_agent.SHORT_RUN["interrupt_after_epochs"],
            )
            return pipeline_agent.shown_run(outcome)

        record = pipeline_agent.run_agent(
            client,
            model,
            project,
            run_training=short_run,
            echo_reasoning=echo_reasoning,
            pause=pause,
        )
        episode = {
            "schema_version": 1,
            "task": "smoke_episode",
            "model_name": model_name,
            "model": model,
            "family": family,
            "start": start,
            "attempt": attempt,
            "record": record,
            "sources": _project_sources(project),
        }
        _write(path, episode)
        episodes.append(episode)
        progress(f"{model_name} {family}: {record['status']}")
    return episodes


def smoke_text(episodes: list[dict[str, Any]]) -> str:
    """What a smoke test showed, and whether the model may write candidates."""
    lines, problems = [], []
    for episode in episodes:
        record = episode["record"]
        steps = record["steps"]
        lengths = sum(step.get("finish_reason") == "length" for step in steps)
        refusals = sum(step.get("finish_reason") == "refusal" for step in steps)
        largest = max((step["output_tokens"] for step in steps), default=0)
        claim = (record["claim"] or {}).get("project_is_correct")
        lines.append(
            f"{episode['family']}: {record['status']}, claims {claim}, "
            f"{record['model_calls']} calls, {record['tool_calls']} tool calls, "
            f"{record['training_runs']} short runs, changed {record['changed_modules'] or 'nothing'}"
        )
        lines.append(
            f"    tokens: {record['input_tokens']} in ({record['cached_input_tokens']} cached), "
            f"{record['output_tokens']} out ({record['reasoning_tokens']} reasoning), "
            f"largest reply {largest} of {pipeline_agent.MAX_OUTPUT_TOKENS}, "
            f"thinking blocks {sum(step.get('thinking_blocks') or 0 for step in steps)}; "
            f"served {record['served_models']}"
        )
        if record["status"] != "finished":
            problems.append(f"{episode['family']} ended {record['status']}")
        if lengths:
            problems.append(f"{episode['family']}: {lengths} replies reached the output limit")
        if refusals:
            problems.append(f"{episode['family']}: {refusals} replies were refusals")
        for error in record["api_errors"]:
            lines.append(f"    API error {error['status_code']}: {error['message'][:200]}")
    lines.append("PASSED" if not problems else "NOT PASSED: " + "; ".join(problems))
    return "\n".join(lines)


def build_parser() -> argparse.ArgumentParser:
    parser = argparse.ArgumentParser(description="The candidates of the challenge set.")
    commands = parser.add_subparsers(dest="command", required=True)
    generated = commands.add_parser("generate", help="Let one model write its candidates.")
    generated.add_argument("--model-name", required=True, choices=challenge_set.MODELS)
    generated.add_argument("--provider", choices=PROVIDERS, required=True)
    generated.add_argument("--model", help="The provider's model, if not its environment variable.")
    generated.add_argument("--echo-reasoning", action="store_true")
    generated.add_argument("--pause", type=float, default=0.0, help="Seconds before every call.")
    ran = commands.add_parser("run", help="Train every candidate and the healthy references.")
    ran.add_argument("--device", default="auto")
    labelled = commands.add_parser("label", help="Run the hidden tests on every candidate.")
    shown = commands.add_parser("summary", help="Say how far a split has come.")
    for command in (generated, ran, labelled, shown):
        command.add_argument("--split", choices=challenge_set.SPLITS, required=True)
    tried = commands.add_parser("smoke", help="Try a model on two development faults.")
    tried.add_argument("--model-name", required=True, choices=challenge_set.MODELS)
    tried.add_argument("--provider", choices=PROVIDERS, required=True)
    tried.add_argument("--model", help="The provider's model, if not its environment variable.")
    tried.add_argument("--echo-reasoning", action="store_true")
    tried.add_argument("--pause", type=float, default=0.0, help="Seconds before every call.")
    return parser


def main(argv: list[str] | None = None) -> int:
    args = build_parser().parse_args(argv)
    if args.command == "smoke":
        client, model = create_llm_client(args.provider, args.model)
        episodes = smoke(
            args.model_name, client, model, echo_reasoning=args.echo_reasoning, pause=args.pause
        )
        print(smoke_text(episodes))
        return 0
    if args.command == "generate":
        client, model = create_llm_client(args.provider, args.model)
        generate(
            args.split,
            args.model_name,
            client,
            model,
            echo_reasoning=args.echo_reasoning,
            pause=args.pause,
        )
    elif args.command == "run":
        run_all(args.split, runner=Runner(ROOT / args.split / "runs", device=args.device))
    elif args.command == "label":
        label_all(args.split)
    print(summary_text(args.split))
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
